export function companionMood(d,time,distance,mounted,night=false){if(!d.tame||mounted)return 'awake';if(distance>10)d.wasAway=true;if(d.wasAway&&distance<4){d.wasAway=false;d.greetingUntil=time+2;d.greet=true;}if((d.petUntil||0)>time)return 'pet';if((d.greetingUntil||0)>time)return 'greet';return night&&d.order==='stay'&&distance>3?'sleep':'awake';}
export function animateCompanion(d,time,mood){d.g.rotation.z=mood==='sleep'?.18:mood==='pet'?Math.sin(time*8)*.06:mood==='greet'?Math.sin(time*12)*.04:0;d.g.rotation.x=mood==='sleep'?-.08:mood==='pet'?Math.sin(time*5)*.04:0;for(const l of d.legs||[])l.rotation.x=mood==='sleep'?.55:mood==='awake'?Math.sin(time*5)*.18:Math.sin(time*7)*.08;}
